def solve():
    import sys
    n, t = map(int, sys.stdin.readline().split())

    # dp[y][d][h][v] = count
    # y in 1..4, d in 0/1 (0=down,1=up), h,v up to t

    max_h = t + 1
    max_v = t + 1

    # initialize for i=1
    dp = {}
    for y in range(1, 5):
        dp[(y, -1, 0, 0)] = 1  # d=-1 means no direction yet

    for i in range(2, n+1):
        ndp = {}
        for (y_prev, d_prev, h, v), cnt in dp.items():
            for y_cur in range(1, 5):
                if y_cur == y_prev:
                    continue
                d_cur = 1 if y_cur > y_prev else 0

                if d_prev == -1:
                    new_h, new_v = h, v
                else:
                    if d_prev == 1 and d_cur == 0:
                        new_h, new_v = h+1, v
                    elif d_prev == 0 and d_cur == 1:
                        new_h, new_v = h, v+1
                    else:
                        new_h, new_v = h, v

                if new_h > t or new_v > t-1:
                    if not (new_h <= t and new_v <= max(t-1, 0)):
                        continue

                if new_h > t:
                    continue
                if new_v > t - 1:
                    continue

                key = (y_cur, d_cur, new_h, new_v)
                ndp[key] = ndp.get(key, 0) + cnt
        dp = ndp

    total = 0
    for (y, d, h, v), cnt in dp.items():
        if h == t and v == t - 1:
            total += cnt

    print(total)

